type LiveEvent = readonly [ChatId, ChatWatchEvent];

export class ChatManagedRuntime extends Context.Service<ChatManagedRuntime>()(
  "ChatManagedRuntime",
  {
    make: Effect.gen(function* () {
      const runtime = yield* ChatRuntime;
      const sessions = yield* ChatSessions;
      const events = yield* Ref.make<
        HashMap.HashMap<ChatId, ReadonlyArray<ChatWatchEvent>>
      >(HashMap.empty());
      const messages = yield* Ref.make<
        HashMap.HashMap<ChatId, ReadonlyArray<ChatMessage>>
      >(HashMap.empty());
      const activeFibers = yield* Ref.make<
        HashMap.HashMap<ChatId, Fiber.Fiber<void, never>>
      >(HashMap.empty());
      const liveEvents = yield* PubSub.unbounded<LiveEvent>();

      const publish = (chatId: ChatId, event: ChatWatchEvent) =>
        Effect.gen(function* () {
          yield* Ref.update(events, (current) =>
            HashMap.set(current, chatId, [
              ...Option.getOrElse(HashMap.get(current, chatId), () => []),
              event,
            ]),
          );
          yield* PubSub.publish(liveEvents, [chatId, event] as const);
        });

      const removeActiveFiber = (chatId: ChatId) =>
        Ref.update(activeFibers, HashMap.remove(chatId));

      return {
        send: ({
          chatId,
          message,
        }: {
          readonly chatId: ChatId;
          readonly message: ChatMessage;
        }): Effect.Effect<
          void,
          ChatNotFoundError | GenerationInProgressError
        > =>
          Effect.gen(function* () {
            yield* sessions.reserve(chatId);

            const userEvent = ChatWatchEvent.cases["user-message"].make({
              message,
            });
            yield* publish(chatId, userEvent);

            const history = yield* Ref.modify(messages, (current) => {
              const nextMessages = [
                ...Option.getOrElse(HashMap.get(current, chatId), () => []),
                message,
              ];
              return [
                nextMessages,
                HashMap.set(current, chatId, nextMessages),
              ] as const;
            });

            const fiber = yield* runtime.generate(history).pipe(
              Stream.tap((part) =>
                publish(
                  chatId,
                  ChatWatchEvent.cases["assistant-part"].make({ part }),
                ),
              ),
              Stream.runDrain,
              Effect.ensuring(sessions.release(chatId)),
              Effect.ensuring(removeActiveFiber(chatId)),
              Effect.forkDetach,
            );

            yield* Ref.update(activeFibers, HashMap.set(chatId, fiber));
          }),
        watch: (chatId: ChatId) =>
          Stream.unwrap(
            Effect.gen(function* () {
              yield* sessions.ensure(chatId);
              const replay = yield* Ref.get(events).pipe(
                Effect.map((current) =>
                  Option.getOrElse(HashMap.get(current, chatId), () => []),
                ),
              );
              const live = Stream.fromPubSub(liveEvents).pipe(
                Stream.filter(([eventChatId]) => eventChatId === chatId),
                Stream.map(([, event]) => event),
              );
              return Stream.fromIterable(replay).pipe(Stream.concat(live));
            }),
          ),
        interrupt: (chatId: ChatId) =>
          Effect.gen(function* () {
            yield* sessions.ensure(chatId);
            const fiber = yield* Ref.get(activeFibers).pipe(
              Effect.map(HashMap.get(chatId)),
            );
            yield* Option.match(fiber, {
              onNone: () => Effect.void,
              onSome: Fiber.interrupt,
            });
          }),
      } as const;
    }),
  },
) {}

export const ChatManagedRuntimeLive = Layer.effect(ChatManagedRuntime)(
  ChatManagedRuntime.make,
);

{{#if runtime=bun}}import { BunCrypto as PlatformCrypto } from "@effect/platform-bun";{{/if}}{{#if runtime=node}}import { NodeCrypto as PlatformCrypto } from "@effect/platform-node";{{/if}}{{#if runtime=deno}}import { DenoCrypto as PlatformCrypto } from "@effect/platform-deno";{{/if}}
import {
  type ClientInfo,
  type WebSocketEvent,
  WebSocketRpc,
} from "@repo/domain/WebSocket";
import { ClientGenerator, PresenceService } from "@repo/presence";
import { DateTime, Effect, Layer, Queue, Stream } from "effect";
import { RpcSerialization, RpcServer } from "effect/unstable/rpc";

const PresenceRpcHandlers = WebSocketRpc.toLayer(
  Effect.gen(function* () {
    const presence = yield* PresenceService;
    const gen = yield* ClientGenerator;
    yield* Effect.logInfo("Starting Presence RPC Live Implementation");

    return WebSocketRpc.of({
      subscribe: Effect.fn(function* () {
        yield* Effect.logDebug("New presence subscription");

        const clientId = yield* gen.generateClientId();
        const connectedAt = yield* DateTime.now;
        const clientInfo: ClientInfo = {
          clientId,
          status: "online",
          connectedAt,
        };

        const queue = yield* Queue.unbounded<WebSocketEvent>();

        // Fork the stream consumer to handle incoming PubSub events
        yield* Effect.forkScoped(
          presence.subscribe.pipe(
            Stream.tap((event) =>
              Effect.gen(function* () {
                // Filter out our own user_joined event since we send "connected" instead
                if (
                  event._tag === "user_joined" &&
                  event.client.clientId === clientId
                ) {
                  return;
                }
                yield* Queue.offer(queue, event);
              }),
            ),
            Stream.runDrain,
            Effect.ensuring(
              Effect.gen(function* () {
                yield* presence.removeClient(clientId);
                yield* Queue.shutdown(queue);
                yield* Effect.logDebug(
                  `Presence subscription ended for ${clientId}`,
                );
              }),
            ),
          ),
        );

        // Get existing clients BEFORE adding ourselves
        const existingClients = presence.getClients();

        // Now add ourselves - this publishes user_joined to PubSub for other clients
        yield* presence.addClient(clientId, clientInfo);

        // Send our own connected event (not user_joined since we're the one connecting)
        yield* Queue.offer(queue, {
          _tag: "connected",
          clientId,
          connectedAt,
        });

        // Send existing clients as user_joined events so we know who's already here
        for (const client of existingClients) {
          yield* Queue.offer(queue, {
            _tag: "user_joined",
            client,
          });
        }

        return queue;
      }),

      setStatus: Effect.fn(function* (payload) {
        yield* Effect.logDebug(
          `Setting status for ${payload.clientId} to ${payload.status}`,
        );
        yield* presence.setStatus(payload.clientId, payload.status);
        return { success: true };
      }),

      getPresence: Effect.fn(function* () {
        const clients = presence.getClients();
        yield* Effect.logDebug(`Returning ${clients.length} clients`);
        return { clients: [...clients] };
      }),
    });
  }),
).pipe(
  Layer.provide(PresenceService.layer),
  Layer.provide(ClientGenerator.layer),
  Layer.provide(PlatformCrypto.layer),
);

export const PresenceRpcLive = RpcServer.layerHttp({
  group: WebSocketRpc,
  path: "/ws",
}).pipe(
  Layer.provide(PresenceRpcHandlers),
  Layer.provide(RpcSerialization.layerNdjson),
);

