import {
  type ChatId,
  type ChatMessage,
  type ChatResponse,
  ChatStreamPart,
  type ToolCall,
} from "@repo/domain/Chat";
import { Effect, Stream } from "effect";
import type { Atom as AtomType } from "effect/unstable/reactivity";
import { runtime } from "../atom";
import { ChatRpcClient } from "../chat-rpc-client";

export const chatStartAtom: AtomType.AtomResultFn<
  void,
  { readonly chatId: ChatId },
  unknown
> = runtime.fn(() =>
  Effect.gen(function* () {
    const rpc = yield* ChatRpcClient;
    return yield* rpc.client.chat_start();
  }).pipe(Effect.provide(ChatRpcClient.layer)),
);

export const accumulateChatResponse = (
  state: ChatResponse,
  part: ChatStreamPart,
): ChatResponse =>
  ChatStreamPart.match(part, {
    text: (part) => {
      const currentSegments = state._tag === "initial" ? [] : state.segments;
      const lastSegment = currentSegments[currentSegments.length - 1];

      if (lastSegment?._tag === "text") {
        return {
          _tag: "streaming",
          segments: [
            ...currentSegments.slice(0, -1),
            {
              _tag: "text",
              content: lastSegment.content + part.delta,
              isComplete: true,
            },
          ],
          reasoning: state._tag === "streaming" ? state.reasoning : undefined,
        };
      }

      return {
        _tag: "streaming",
        segments: [
          ...currentSegments,
          {
            _tag: "text",
            content: part.delta,
            isComplete: true,
          },
        ],
        reasoning: state._tag === "streaming" ? state.reasoning : undefined,
      };
    },

    reasoning: (part) => {
      const currentSegments = state._tag === "initial" ? [] : state.segments;
      return {
        _tag: "streaming",
        segments: currentSegments,
        reasoning:
          (state._tag === "streaming" ? (state.reasoning ?? "") : "") +
          part.delta,
      };
    },

    "tool-start": (part) => {
      const currentSegments = state._tag === "initial" ? [] : state.segments;
      return {
        _tag: "streaming",
        segments: [
          ...currentSegments,
          {
            _tag: "tool-call",
            tool: {
              id: part.id,
              name: part.name,
              status: "running",
              ...(part.input === undefined ? {} : { input: part.input }),
            },
          },
        ],
        reasoning: state._tag === "streaming" ? state.reasoning : undefined,
      };
    },

    "tool-success": (part) =>
      updateToolResult(state, {
        id: part.id,
        status: "complete",
        result: part.output,
      }),

    "tool-failure": (part) =>
      updateToolResult(state, {
        id: part.id,
        status: "failed",
        result: part.error,
      }),

    finish: (part) => {
      const segments = state._tag === "streaming" ? state.segments : [];
      return {
        _tag: "complete",
        segments,
        usage: part.usage,
        finishReason: part.reason,
      };
    },

    error: (part) => {
      const segments = state._tag === "streaming" ? state.segments : [];
      return {
        _tag: "error",
        segments,
        error: {
          message: part.message,
          recoverable: part.recoverable,
        },
      };
    },
  });

const updateToolResult = (
  state: ChatResponse,
  update: {
    id: string;
    status: ToolCall["status"];
    result: string;
  },
): ChatResponse => {
  if (state._tag !== "streaming") return state;
  return {
    ...state,
    segments: state.segments.map((seg) =>
      seg._tag === "tool-call" && seg.tool.id === update.id
        ? {
            ...seg,
            tool: {
              ...seg.tool,
              status: update.status,
              result: update.result,
            },
          }
        : seg,
    ),
  };
};

export const chatAtom: AtomType.AtomResultFn<
  {
    readonly chatId: ChatId;
    readonly messages: readonly ChatMessage[];
  },
  ChatResponse,
  unknown
> = runtime.fn(({ chatId, messages }) => {
  return Stream.unwrap(
    Effect.gen(function* () {
      const rpc = yield* ChatRpcClient;
      return rpc.client.chat_ask({ chatId, messages });
    }),
  ).pipe(
    Stream.provide(ChatRpcClient.layer),
    Stream.tapError((error: unknown) =>
      Effect.logError("[chatAtom] Stream error occurred:", error),
    ),
    Stream.scan(
      () => ({ _tag: "initial" as const }),
      accumulateChatResponse,
    ),
    Stream.drop(1),
    Stream.catch((error: unknown) => {
      const errorMessage =
        error instanceof Error
          ? `Stream failed: ${error.message}`
          : `Stream failed: ${String(error)}`;
      return Stream.make({
        _tag: "error" as const,
        segments: [],
        error: {
          message: errorMessage,
          recoverable: false,
        },
      } as ChatResponse);
    }),
  );
});

import { useAtom } from "@effect/atom-react";
import type { ChatId, ChatResponse, MessageSegment } from "@repo/domain/Chat";
import { Cause } from "effect";
import { AsyncResult } from "effect/unstable/reactivity";
import {
  CircleAlertIcon,
  CircleCheckIcon,
  LoaderCircleIcon,
} from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { Bubble, BubbleContent } from "@/components/ui/bubble";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Marker, MarkerContent, MarkerIcon } from "@/components/ui/marker";
import {
  Message,
  MessageContent,
  MessageFooter,
  MessageGroup,
} from "@/components/ui/message";
import {
  MessageScroller,
  MessageScrollerButton,
  MessageScrollerContent,
  MessageScrollerItem,
  MessageScrollerProvider,
  MessageScrollerViewport,
} from "@/components/ui/message-scroller";
import { chatAtom, chatStartAtom } from "@/lib/atoms/chat-atom";

type ChatEntry = {
  id: string;
  role: "user" | "assistant" | "system";
  message: string;
  segments?: readonly MessageSegment[];
  usage?:
    | {
        promptTokens: number;
        completionTokens: number;
        totalTokens: number;
      }
    | undefined;
  finishReason?: string | undefined;
};

const EMPTY_SEGMENTS: readonly MessageSegment[] = [];

export function ChatBox() {
  const [result, runChat] = useAtom(chatAtom);
  const [startResult, startChat] = useAtom(chatStartAtom);
  const [chatId, setChatId] = useState<ChatId | null>(null);
  const [input, setInput] = useState("");
  const [history, setHistory] = useState<ChatEntry[]>([]);
  const lastSentMessagesRef = useRef<
    Array<{
      role: "user" | "assistant" | "system";
      content: string;
    }>
  >([]);
  const pendingMessagesRef = useRef<typeof lastSentMessagesRef.current | null>(
    null,
  );
  const readinessAttemptRef = useRef(0);
  const lastCompletionKeyRef = useRef<string | null>(null);
  const entryIdRef = useRef(0);
  const nextEntryId = () => {
    entryIdRef.current += 1;
    return `chat-entry-${entryIdRef.current}`;
  };

  const currentResult: ChatResponse = AsyncResult.getOrElse(
    result,
    () => ({ _tag: "initial" }) as const,
  );

  const currentSegments =
    currentResult._tag === "initial" ? EMPTY_SEGMENTS : currentResult.segments;

  const isWaiting = AsyncResult.isWaiting(result);
  const isStarting = AsyncResult.isWaiting(startResult);
  const isFailure = AsyncResult.isFailure(result);
  const isStreaming = currentResult._tag === "streaming";
  const asyncFailureMessage = isFailure ? Cause.pretty(result.cause) : null;

  useEffect(() => {
    const started = AsyncResult.getOrElse(startResult, () => null);
    if (!started) return;
    setChatId(started.chatId);
    const pending = pendingMessagesRef.current;
    if (!pending) return;
    pendingMessagesRef.current = null;
    runChat({ chatId: started.chatId, messages: pending });
  }, [runChat, startResult]);

  const sendMessages = (
    messages: Array<{
      role: "user" | "assistant" | "system";
      content: string;
    }>,
  ) => {
    lastSentMessagesRef.current = messages;
    readinessAttemptRef.current = 0;
    if (chatId) {
      runChat({ chatId, messages });
      return;
    }
    pendingMessagesRef.current = messages;
    startChat();
  };

  useEffect(() => {
    if (!isFailure) return;
    if (currentResult._tag !== "error" || !currentResult.error.recoverable) {
      return;
    }
    if (lastSentMessagesRef.current.length === 0) return;
    if (readinessAttemptRef.current >= 3) return;

    readinessAttemptRef.current += 1;
    const timeoutId = window.setTimeout(() => {
      if (chatId) {
        runChat({ chatId, messages: lastSentMessagesRef.current });
        return;
      }
      pendingMessagesRef.current = lastSentMessagesRef.current;
      startChat();
    }, 600 * readinessAttemptRef.current);

    return () => window.clearTimeout(timeoutId);
  }, [chatId, currentResult, isFailure, runChat, startChat]);

  const handleSend = () => {
    if (!input.trim()) return;
    const userMsg: ChatEntry = {
      id: nextEntryId(),
      role: "user",
      message: input,
    };
    setHistory((prev) => [...prev, userMsg]);
    setInput("");

    const messages = historyToMessages([...history, userMsg]);
    sendMessages(messages);
  };

  const displayHistory =
    currentResult._tag === "streaming" && currentResult.segments.length > 0
      ? [
          ...history,
          {
            id: `streaming-${chatId ?? "pending"}`,
            role: "assistant" as const,
            message: "",
            segments: currentResult.segments,
          },
        ]
      : history;

  const completionSnapshot = useMemo(() => {
    if (currentResult._tag !== "complete") return null;
    if (currentResult.segments.length === 0) return null;
    return {
      segments: currentResult.segments,
      usage: currentResult.usage,
      finishReason: currentResult.finishReason,
    };
  }, [currentResult]);

  useEffect(() => {
    if (!completionSnapshot) return;
    const completionKey = JSON.stringify(completionSnapshot);
    if (lastCompletionKeyRef.current === completionKey) return;
    lastCompletionKeyRef.current = completionKey;
    setHistory((prev) => [
      ...prev,
      {
        id: nextEntryId(),
        role: "assistant",
        message: "",
        segments: completionSnapshot.segments,
        usage: completionSnapshot.usage,
        finishReason: completionSnapshot.finishReason,
      },
    ]);
  }, [completionSnapshot]);

  return (
    <Card className="flex h-full w-full flex-col">
      <CardHeader>
        <CardTitle>Chat (RPC)</CardTitle>
        <div className="mt-1 flex flex-wrap gap-2">
          {chatId && (
            <Marker className="w-fit rounded-none border border-border bg-muted px-2 py-0.5 font-mono text-[0.65rem]">
              <MarkerContent>{chatId}</MarkerContent>
            </Marker>
          )}
          {isStarting && <StatusMarker label="Starting" status="pending" />}
          {isStreaming && <StatusMarker label="Streaming" status="active" />}
          {isWaiting && !isStreaming && (
            <StatusMarker label="Loading" status="pending" />
          )}
          {isFailure && <StatusMarker label="Error" status="error" />}
        </div>
      </CardHeader>

      <CardContent className="flex min-h-0 flex-1 flex-col gap-0 p-0">
        <MessageScrollerProvider>
          <MessageScroller className="flex-1">
            <MessageScrollerViewport className="px-4">
              <MessageScrollerContent className="py-6">
                {displayHistory.length === 0 &&
                  currentSegments.length === 0 && (
                    <Marker variant="border" className="bg-muted/50 px-4 py-6">
                      <MarkerContent className="flex flex-col gap-2">
                        <span className="text-[0.65rem] uppercase tracking-[0.28em]">
                          Empty channel
                        </span>
                        <span className="text-xs text-foreground">
                          Start with a clear request.
                        </span>
                      </MarkerContent>
                    </Marker>
                  )}

                {displayHistory.map((msg, i) => (
                  <MessageScrollerItem
                    key={msg.id}
                    scrollAnchor={i === displayHistory.length - 1}
                  >
                    {msg.role === "user" ? (
                      <Message align="end">
                        <MessageContent>
                          <Bubble align="end">
                            <BubbleContent className="whitespace-break-spaces">
                              {msg.message}
                            </BubbleContent>
                          </Bubble>
                        </MessageContent>
                      </Message>
                    ) : (
                      <Message align="start">
                        <MessageContent>
                          <MessageGroup>
                            {msg.segments?.map((segment, segIdx) => (
                              <AssistantSegment
                                // biome-ignore lint/suspicious/noArrayIndexKey: stable order
                                key={segIdx}
                                segment={segment}
                              />
                            ))}
                          </MessageGroup>
                          {msg.usage && msg.finishReason && (
                            <MessageFooter className="text-[0.6rem]">
                              {msg.usage.totalTokens} tokens |{" "}
                              {msg.finishReason}
                            </MessageFooter>
                          )}
                        </MessageContent>
                      </Message>
                    )}
                  </MessageScrollerItem>
                ))}

                {currentResult._tag === "streaming" &&
                  currentResult.reasoning && (
                    <Marker>
                      <MarkerContent className="shimmer">
                        Reasoning: {currentResult.reasoning}
                      </MarkerContent>
                    </Marker>
                  )}

                {currentResult._tag === "error" && (
                  <Bubble variant="destructive" className="max-w-full">
                    <BubbleContent className="flex flex-col gap-2">
                      <p className="font-medium">
                        {currentResult.error.message}
                      </p>
                      {currentResult.error.recoverable && (
                        <Button
                          variant="outline"
                          size="sm"
                          className="mt-2"
                          onClick={() => {
                            const messages = historyToMessages(history);
                            sendMessages(messages);
                          }}
                        >
                          Retry
                        </Button>
                      )}
                    </BubbleContent>
                  </Bubble>
                )}

                {asyncFailureMessage && currentResult._tag !== "error" && (
                  <Bubble variant="destructive" className="max-w-full">
                    <BubbleContent>
                      <pre className="whitespace-pre-wrap text-xs">
                        {asyncFailureMessage}
                      </pre>
                    </BubbleContent>
                  </Bubble>
                )}
              </MessageScrollerContent>
            </MessageScrollerViewport>
            <MessageScrollerButton />
          </MessageScroller>
        </MessageScrollerProvider>

        <div className="border-t border-border p-4">
          <div className="flex w-full gap-2">
            <Input
              type="text"
              placeholder="Send a message"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleSend()}
              disabled={isStarting || isWaiting || isStreaming}
            />
            <Button
              onClick={handleSend}
              disabled={!input.trim() || isStarting || isWaiting || isStreaming}
            >
              Send
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

function StatusMarker({
  label,
  status,
}: {
  label: string;
  status: "active" | "error" | "pending";
}) {
  const Icon =
    status === "error"
      ? CircleAlertIcon
      : status === "active"
        ? CircleCheckIcon
        : LoaderCircleIcon;

  return (
    <Marker variant={status === "active" ? "border" : "default"}>
      <MarkerIcon
        className={
          status === "error"
            ? "text-destructive"
            : status === "pending"
              ? "animate-spin"
              : undefined
        }
      >
        <Icon />
      </MarkerIcon>
      <MarkerContent>{label}</MarkerContent>
    </Marker>
  );
}

function AssistantSegment({ segment }: { segment: MessageSegment }) {
  return segment._tag === "text" ? (
    <Bubble variant="ghost" className="max-w-full">
      <BubbleContent className="whitespace-pre-wrap">
        {segment.content}
      </BubbleContent>
    </Bubble>
  ) : (
    <Bubble variant="muted" className="max-w-full">
      <BubbleContent>
        <Marker>
          <MarkerContent className="font-mono">
            Tool: {segment.tool.name} [{segment.tool.status}]
          </MarkerContent>
        </Marker>
        {segment.tool.result && (
          <pre className="mt-2 overflow-auto text-xs">
            {segment.tool.result}
          </pre>
        )}
      </BubbleContent>
    </Bubble>
  );
}

const historyToMessages = (messages: ChatEntry[]) =>
  messages.map((msg) => {
    if (msg.role === "assistant" && msg.segments) {
      const textContent = msg.segments.reduce(
        (content, seg) =>
          seg._tag === "text" ? content + seg.content : content,
        "",
      );
      return {
        role: msg.role,
        content: textContent || msg.message,
      };
    }
    return {
      role: msg.role,
      content: msg.message,
    };
  });

import { BrowserSocket } from "@effect/platform-browser";
import type { WebSocketEvent } from "@repo/domain/WebSocket";
import { WebSocketRpc } from "@repo/domain/WebSocket";
import { type Cause, Effect, Layer, Stream } from "effect";
import { type Atom, AtomRpc } from "effect/unstable/reactivity";
import {
  RpcClient,
  type RpcClientError,
  RpcSerialization,
} from "effect/unstable/rpc";

const WS_URL = import.meta.env.VITE_WS_URL || "ws://localhost:9000/ws";

export class WebSocketClient extends AtomRpc.Service<WebSocketClient>()(
  "WebSocketClient",
  {
    group: WebSocketRpc,
    protocol: RpcClient.layerProtocolSocket({
      retryTransientErrors: true,
    }).pipe(
      Layer.provide(BrowserSocket.layerWebSocket(WS_URL)),
      Layer.provide(RpcSerialization.layerNdjson),
    ),
  },
) {}

export const presenceSubscriptionAtom: Atom.AtomResultFn<
  void,
  readonly WebSocketEvent[],
  RpcClientError.RpcClientError | Cause.NoSuchElementError
> = WebSocketClient.runtime.fn(() =>
  Effect.gen(function* () {
    yield* Effect.logDebug("Starting presence subscription stream");
    const client = yield* WebSocketClient;
    // biome-ignore lint/suspicious/noConfusingVoidType: RPC with no payload requires void argument
    return client("subscribe", undefined as void);
  }).pipe(
    Effect.map((stream) =>
      stream.pipe(
        // NOTE: Cap event accumulation at 100 to prevent memory growth in long sessions.
        Stream.scan<WebSocketEvent[], WebSocketEvent>(() => [], (acc, event) => {
          const updated = [...acc, event];
          return updated.length > 100 ? updated.slice(-100) : updated;
        }),
      ),
    ),
    Stream.unwrap,
  ),
);

import { useAtom, useAtomSet } from "@effect/atom-react";
import type {
  ClientId,
  ClientInfo,
  ClientStatus,
  WebSocketEvent,
} from "@repo/domain/WebSocket";
import { AsyncResult } from "effect/unstable/reactivity";
import { useEffect, useMemo } from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  presenceSubscriptionAtom,
  WebSocketClient,
} from "@/lib/web-socket-client";

const buildClientListFromEvents = (
  events: readonly WebSocketEvent[],
): {
  clients: Map<typeof ClientId.Type, ClientInfo>;
  myClientId: typeof ClientId.Type | null;
} => {
  const clients = new Map<typeof ClientId.Type, ClientInfo>();
  let myClientId: typeof ClientId.Type | null = null;

  for (const event of events) {
    switch (event._tag) {
      case "connected":
        myClientId = event.clientId;
        clients.set(event.clientId, {
          clientId: event.clientId,
          status: "online",
          connectedAt: event.connectedAt,
        });
        break;

      case "user_joined":
        clients.set(event.client.clientId, event.client);
        break;

      case "status_changed": {
        const existing = clients.get(event.clientId);
        if (existing) {
          clients.set(event.clientId, {
            ...existing,
            status: event.status,
          });
        }
        break;
      }

      case "user_left":
        clients.delete(event.clientId);
        break;
    }
  }

  return { clients, myClientId };
};

export function PresencePanel({ className }: { className?: string }) {
  const [eventsResult, startSubscription] = useAtom(presenceSubscriptionAtom);
  const setStatus = useAtomSet(WebSocketClient.mutation("setStatus"));

  useEffect(() => {
    startSubscription();
  }, [startSubscription]);

  const events = AsyncResult.getOrElse(
    eventsResult,
    () => [] as readonly WebSocketEvent[],
  );

  const { clients: clientMap, myClientId } = useMemo(
    () => buildClientListFromEvents(events),
    [events],
  );

  const clients = useMemo(() => Array.from(clientMap.values()), [clientMap]);

  const handleSetStatus = (status: ClientStatus) => {
    if (!myClientId) {
      return;
    }
    setStatus({
      payload: { clientId: myClientId, status },
    });
  };

  const getStatusColor = (status: ClientStatus) => {
    switch (status) {
      case "online":
        return "bg-primary";
      case "away":
        return "bg-secondary";
      case "busy":
        return "bg-destructive";
      default:
        return "bg-muted-foreground";
    }
  };

  const isConnected = AsyncResult.isSuccess(eventsResult);
  const isConnecting = AsyncResult.isInitial(eventsResult);

  return (
    <Card className={cn("flex h-full flex-col", className)}>
      <CardHeader>
        <div className="flex items-center justify-between gap-2">
          <div>
            <CardTitle>WebSocket Presence (RPC)</CardTitle>
            <p className="text-xs text-muted-foreground">Realtime status updates over RPC.</p>
          </div>
          <span
            className={cn(
              "inline-flex items-center rounded-full border px-2 py-0.5 text-[0.65rem]",
              isConnected
                ? "border-primary/30 bg-primary/10 text-primary"
                : isConnecting
                  ? "border-secondary/50 bg-secondary text-secondary-foreground"
                  : "border-destructive/40 bg-destructive/10 text-destructive",
            )}
          >
            {isConnected && myClientId
              ? "connected"
              : isConnecting
                ? "connecting"
                : "disconnected"}
          </span>
        </div>
      </CardHeader>

      <CardContent className="flex flex-col gap-4">
        <div className="flex gap-2">
          <Button
            onClick={() => handleSetStatus("online")}
            className="flex-1"
            disabled={!isConnected || !myClientId}
          >
            Online
          </Button>
          <Button
            variant="secondary"
            onClick={() => handleSetStatus("away")}
            className="flex-1"
            disabled={!isConnected || !myClientId}
          >
            Away
          </Button>
          <Button
            variant="outline"
            onClick={() => handleSetStatus("busy")}
            className="flex-1"
            disabled={!isConnected || !myClientId}
          >
            Busy
          </Button>
        </div>

        <div className="rounded-none border border-border bg-muted/50 p-3">
          <h4 className="mb-2 font-medium text-foreground text-xs uppercase tracking-[0.2em]">
            Connected Clients ({clients.length})
          </h4>
          {clients.length === 0 ? (
            <p className="text-muted-foreground text-xs">
              No clients connected
            </p>
          ) : (
            <ul className="space-y-1">
              {clients.map((client: ClientInfo) => (
                <li
                  key={client.clientId}
                  className="flex items-center gap-2 text-xs"
                >
                  <span
                    className={cn(
                      "h-2 w-2 rounded-full",
                      getStatusColor(client.status),
                    )}
                  />
                  <span className="font-mono text-muted-foreground">
                    {client.clientId.slice(0, 8)}...
                  </span>
                  <span className="text-muted-foreground">
                    ({client.status})
                  </span>
                  {client.clientId === myClientId && (
                    <span className="text-primary text-[0.6rem] uppercase tracking-[0.2em]">
                      you
                    </span>
                  )}
                </li>
              ))}
            </ul>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

