        ApiFailure: ({ error }) =>
          h.div(
            [
              h.Class(
                "flex-1 rounded-lg border bg-card p-6 text-card-foreground shadow-sm",
              ),
            ],
            [
              h.h3(
                [h.Class("font-semibold leading-none tracking-tight mb-4")],
