  const mappedCommands = cmds.map(
    Command.mapEffect(
      Effect.map((message) => Presence.GotMessage({ message })),
    ),
  ) as ReadonlyArray<Command.Command<Message>>;
  return [{ ...model, presence: nextChild }, mappedCommands];
}

